sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    (function testFindUsersAndStoreInField() {
        // Replace with the sys_id of the record you want to test
        var recordSysID = current.sys_id; // Example: '1234567890abcdef'

        // Load the record
        var gr = new GlideRecord('x_hsb11_mss_oper_0_operation_request_case'); // Replace 'YOUR_TABLE_NAME' with the actual table name
        if (!gr.get(recordSysID)) {
            gs.error('Record not found with sys_id: ' + recordSysID);
            return;
        }

        // Simulate the main script logic
        try {
            // Get the sys_id of the user creating the record
            var creatorSysID = gr.opened_by.toString(); // Replace 'requestor' with the correct field name
           // gs.info('Creator sys_id: ' + creatorSysID);

            // Fetch the groups the creator belongs to
            var creatorGroups = getUserGroups(creatorSysID);
           // gs.info('Creator Groups: ' + JSON.stringify(creatorGroups));

            if (!creatorGroups || creatorGroups.length === 0) {
               // gs.info('No groups found for the user creating the record.');
                return;
            }

            // Separate groups by type (location, product, requesting site)
            var locationGroups = creatorGroups.filter(group => group.name.match(/^Infodir-iQube-[A-Za-z0-9-]+-PRM-HBAP-[A-Z]{2}$/)); // Match location group pattern

            // Fetch the product team selected on the case
        var productTeam = gr.product_team.toString(); // Replace 'product_team' with the correct field name
       // gs.info('Product Team selected on the case: ' + productTeam);

        // Filter product groups based on the product team
        var productGroups = creatorGroups.filter(group => group.name.match(new RegExp(`^Infodir-iQube-[A-Za-z0-9-]+-PRM-${productTeam}$`))); // Match product group pattern dynamically
        gs.info('Filtered Product Groups: ' + JSON.stringify(productGroups));

            if (locationGroups.length === 0 && productGroups.length === 0) {
               // gs.info('Group lengths - Location: ' + locationGroups.length + ', Product: ' + productGroups.length);
               // gs.info('User does not belong to any of the group types.');
                return;
            }

            // Find users who belong to all three group types
            var usersToNotify = findUsersInGroups(locationGroups, productGroups);
            gs.info('users to notify ' + usersToNotify);

            // Store the email addresses in the user_notify field
            if (usersToNotify.length > 0) {
                var emailAddresses = usersToNotify.map(userSysID => getUserEmail(userSysID)).filter(email => email); // Get valid email addresses
                //gr.user_notify = emailAddresses.join(','); // Store as a comma-separated list
                // gr.update(); // Save the changes to the record
                //gs.info('User notification list updated: ' + emailAddresses.join(','));
                var emailadd = emailAddresses.join(',');
                current.prm_user_email_lst = emailadd;
                current.update();
            } else {
                //gs.info('No users found who belong to both group types.');
            }
        } catch (err) {
            gs.error('Error finding users and storing in user_notify field: ' + err.message + '\n' + err.stack);
        }

        // Function to fetch groups for a user
        function getUserGroups(userSysID) {
            var groups = [];
            var gr = new GlideRecord('sys_user_grmember');
            gr.addQuery('user', userSysID);
            gr.query();
            while (gr.next()) {
                groups.push({
                    sys_id: gr.group.sys_id.toString(),
                    name: gr.group.name.toString()
                });
            }
            return groups;
        }

        // Function to find users who belong to both the group types
        function findUsersInGroups(locationGroups, productGroups) {
            var usersInAllGroups = [];
            var locationGroupIDs = locationGroups.map(group => group.sys_id);
            var productGroupIDs = productGroups.map(group => group.sys_id);

            // Log the group IDs for debugging
           // gs.info('Location Group IDs: ' + locationGroupIDs.join(','));
            //gs.info('Product Group IDs: ' + productGroupIDs.join(','));

            // Collect users for each group type
            var locationUsers = getUsersInGroups(locationGroupIDs);
            var productUsers = getUsersInGroups(productGroupIDs);

            // Find common users across both groups
            usersInAllGroups = locationUsers.filter(user => productUsers.includes(user));

            // Log the results
           // if (usersInAllGroups.length > 0) {
               // gs.info('Common users in both groups: ' + usersInAllGroups.join(','));
           // } else {
               // gs.info('No users found who are part of both groups.');
            //}

            return usersInAllGroups;

            // Helper function to get users in specified groups
            function getUsersInGroups(groupIDs) {
                var users = [];
                if (groupIDs.length === 0) {
                   // gs.error('No group IDs provided.');
                    return users; // Return an empty array
                }

                var gr = new GlideRecord('sys_user_grmember');
                gr.addQuery('group', 'IN', groupIDs.join(',')); // Query users in the specified groups
                gr.query();
                while (gr.next()) {
                    var userSysID = gr.user.sys_id.toString();
                    if (!users.includes(userSysID)) {
                        users.push(userSysID);
                    }
                }

                // Log the users found for debugging
               // gs.info('Users found for groups [' + groupIDs.join(',') + ']: ' + users.join(','));
                return users;
            }
        }
        // Function to get the email address of a user
        function getUserEmail(userSysID) {
            var gr = new GlideRecord('sys_user');
            gr.addQuery('sys_id', userSysID);
            gr.query();
            if (gr.next()) {
                return gr.email.toString();
            }
            return null;
        }
    })();

})(current, previous);
